import (
	"encoding/json"
	"os"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsPaths 是每仓库阈值配置文件的候选路径，按顺序取第一个能读到的。
//
// 服务从仓库根启动时配置在 "inventory/thresholds.json"；`go test` 的工作目录是
// 包目录 inventory/，此时包内的 "thresholds.json" 就是同一个文件。
var thresholdsPaths = []string{
	"inventory/thresholds.json",
	"thresholds.json",
}

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 在阈值配置文件里配置过的仓库用自己的值；没配、或文件不存在/读不出/解析失败，
// 都回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	return thresholdFor(warehouse, loadThresholds())
}

// thresholdFor 在已加载的配置里查这个仓库的阈值，没配就用默认值。
func thresholdFor(warehouse string, thresholds map[string]int) int {
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取并解析阈值配置。任何读取或解析失败都当作「没有配置」，
// 由调用方回退到默认值。
func loadThresholds() map[string]int {
	for _, path := range thresholdsPaths {
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		thresholds := make(map[string]int)
		if err := json.Unmarshal(data, &thresholds); err != nil {
			continue
		}
		return thresholds
	}
	return nil
}

