package inventory

import (
	"os"
	"path/filepath"
	"reflect"
	"testing"
)

// pointThresholdsAt 把阈值配置指向指定文件，测试结束后恢复原有候选路径。
func pointThresholdsAt(t *testing.T, path string) {
	t.Helper()
	original := thresholdsPaths
	t.Cleanup(func() { thresholdsPaths = original })
	thresholdsPaths = []string{path}
}

// writeThresholds 把内容写进临时文件并返回其路径。
func writeThresholds(t *testing.T, content string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatalf("写临时阈值文件失败: %v", err)
	}
	return path
}

func TestConfiguredWarehouseUsesOwnThreshold(t *testing.T) {
	pointThresholdsAt(t, writeThresholds(t, `{"shanghai": 20}`))

	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(shanghai) = %d, 期望 20", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库应回退默认值，得到 %d", got)
	}
}

func TestIsLowStockUsesPerWarehouseThreshold(t *testing.T) {
	pointThresholdsAt(t, writeThresholds(t, `{"shanghai": 20}`))

	if !IsLowStock("shanghai", 19) {
		t.Fatal("19 低于 shanghai 的阈值 20，应当算低库存")
	}
	if IsLowStock("shanghai", 20) {
		t.Fatal("20 等于 shanghai 的阈值，不算低库存（严格小于）")
	}
}

func TestMissingThresholdsFileFallsBack(t *testing.T) {
	pointThresholdsAt(t, filepath.Join(t.TempDir(), "does-not-exist.json"))

	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("文件不存在应回退默认值，得到 %d", got)
	}
}

func TestMalformedThresholdsFileFallsBack(t *testing.T) {
	pointThresholdsAt(t, writeThresholds(t, `{"shanghai":`))

	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("配置解析失败应回退默认值，得到 %d", got)
	}
}

func TestLowStockWarehousesUsesPerWarehouseThresholds(t *testing.T) {
	pointThresholdsAt(t, writeThresholds(t, `{"shanghai": 20}`))

	got := LowStockWarehouses(map[string]int{
		"shanghai": 15, // 低于自己配置的 20
		"chengdu":  4,  // 低于默认 5
		"wuhan":    5,  // 等于默认 5，不算
	})
	want := []string{"chengdu", "shanghai"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
	}
}
